  ascii : '.:-=+*#%@&$',
  wire  : '/\\|-_+*<>[]{}()=~^',
  binary: '01',
  matrix: 'アイウエオカキクケコサシスセソタチツテトナニヌネノ0123456789',
  runes : '◈◉◇◆▲▼◢◣⌒⌘◎▣',
