  spectrum: { sat: 100, hue: r => r() * 360 },
  acid    : { sat: 100, hue: r => [95, 150, 300][(r() * 3) | 0] + r() * 34 },
  ember   : { sat: 100, hue: r => r() * 52 },
  ice     : { sat: 100, hue: r => 172 + r() * 92 },
  vapor   : { sat: 100, hue: r => [318, 188, 272][(r() * 3) | 0] + r() * 22 },
  mono    : { sat: 0,   hue: () => 0 }
